INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg01', 'exercise', 'c1w02', 1050, '{"id":"xg01","lessonId":"c1w02","skill":"grammar","type":"mcq","prompt":"Choose the correct plural: una città italiana → …","answer":"due città italiane","explanation":"Città does not change; the adjective becomes feminine plural.","options":["due città italiani","due città italiane","due cittè italiane"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg02', 'exercise', 'c1w03', 1051, '{"id":"xg02","lessonId":"c1w03","skill":"grammar","type":"mcq","prompt":"Complete: Noi ___ trent’anni.","answer":"abbiamo","explanation":"Italian uses avere for age.","options":["siamo","abbiamo","avete"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg03', 'exercise', 'c1w04', 1052, '{"id":"xg03","lessonId":"c1w04","skill":"grammar","type":"mcq","prompt":"Which question asks about somebody’s job?","answer":"Che lavoro fai?","explanation":"Che lavoro fai? is the standard informal question.","options":["Dove lavoro fai?","Che lavoro fai?","Quanto lavoro sei?"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg04', 'exercise', 'c1w05', 1053, '{"id":"xg04","lessonId":"c1w05","skill":"grammar","type":"mcq","prompt":"Choose the polite request.","answer":"Potrei avere il menù?","explanation":"Potrei avere…? is a polite transactional formula.","options":["Dammi il menù.","Potrei avere il menù?","Tu porti menù."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg05', 'exercise', 'c1w06', 1054, '{"id":"xg05","lessonId":"c1w06","skill":"grammar","type":"mcq","prompt":"Complete: Marco ___ a tennis ogni sabato.","answer":"gioca","explanation":"Marco is third-person singular.","options":["gioco","gioca","giocano"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg06', 'exercise', 'c1w07', 1055, '{"id":"xg06","lessonId":"c1w07","skill":"grammar","type":"mcq","prompt":"Complete: A Laura ___ il jazz.","answer":"piace","explanation":"Jazz is singular, so use piace.","options":["piace","piacciono","piaci"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg07', 'exercise', 'c1w08', 1056, '{"id":"xg07","lessonId":"c1w08","skill":"grammar","type":"mcq","prompt":"Which means ‘on the second floor’?","answer":"al secondo piano","explanation":"Floors use a + article: al secondo piano.","options":["nel due piano","al secondo piano","a secondo piano"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg08', 'exercise', 'c1w11', 1057, '{"id":"xg08","lessonId":"c1w11","skill":"grammar","type":"mcq","prompt":"Complete: Anna ___ alle sette.","answer":"si sveglia","explanation":"The reflexive pronoun for Anna is si.","options":["mi sveglia","si sveglia","sveglia si"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg09', 'exercise', 'c1w12', 1058, '{"id":"xg09","lessonId":"c1w12","skill":"grammar","type":"mcq","prompt":"Choose the correct modal construction.","answer":"Possiamo entrare?","explanation":"A modal verb takes the infinitive directly.","options":["Possiamo entriamo?","Possiamo entrare?","Possiamo di entrare?"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg10', 'exercise', 'c1w13', 1059, '{"id":"xg10","lessonId":"c1w13","skill":"grammar","type":"mcq","prompt":"Complete: Giulia e Marta sono ___ ieri.","answer":"partite","explanation":"After essere, the participle agrees with feminine plural subjects.","options":["partito","partiti","partite"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg11', 'exercise', 'c1w14', 1060, '{"id":"xg11","lessonId":"c1w14","skill":"grammar","type":"mcq","prompt":"Replace ‘il libro’: Leggo il libro.","answer":"Lo leggo.","explanation":"Lo replaces a masculine singular direct object.","options":["La leggo.","Lo leggo.","Gli leggo."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg12', 'exercise', 'c1w15', 1061, '{"id":"xg12","lessonId":"c1w15","skill":"grammar","type":"mcq","prompt":"Choose: Compro ___ arance.","answer":"delle","explanation":"The feminine plural partitive is delle.","options":["del","dell’","delle"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg13', 'exercise', 'c1w16', 1062, '{"id":"xg13","lessonId":"c1w16","skill":"grammar","type":"mcq","prompt":"Complete: Questi sono ___ genitori.","answer":"i miei","explanation":"Plural family nouns take the article and matching possessive.","options":["miei","i miei","le mie"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg14', 'exercise', 'c1w19', 1063, '{"id":"xg14","lessonId":"c1w19","skill":"grammar","type":"mcq","prompt":"Which frequency phrase means ‘twice a week’?","answer":"due volte alla settimana","explanation":"Volta means occurrence; alla settimana gives the period.","options":["due tempo settimana","due volte alla settimana","seconda settimana"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg15', 'exercise', 'c1w20', 1064, '{"id":"xg15","lessonId":"c1w20","skill":"grammar","type":"mcq","prompt":"Complete: In cucina ___ un tavolo.","answer":"c’è","explanation":"Use c’è with one thing.","options":["c’è","ci sono","sono"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg16', 'exercise', 'c2w05', 1065, '{"id":"xg16","lessonId":"c2w05","skill":"grammar","type":"mcq","prompt":"The station is between the bank and the bar.","answer":"La stazione è tra la banca e il bar.","explanation":"Tra/fra means between.","options":["La stazione è sopra la banca.","La stazione è tra la banca e il bar.","La stazione è dalla banca."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg17', 'exercise', 'c2w06', 1066, '{"id":"xg17","lessonId":"c2w06","skill":"grammar","type":"mcq","prompt":"Which expression asks for still water?","answer":"dell’acqua naturale","explanation":"Naturale is the usual restaurant contrast with frizzante.","options":["dell’acqua naturale","un’acqua natura","della naturale acqua"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg18', 'exercise', 'c2w07', 1067, '{"id":"xg18","lessonId":"c2w07","skill":"grammar","type":"mcq","prompt":"Combine a + gli uffici.","answer":"agli uffici","explanation":"A + gli becomes agli.","options":["ai uffici","agli uffici","alle uffici"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg19', 'exercise', 'c2w08', 1068, '{"id":"xg19","lessonId":"c2w08","skill":"grammar","type":"mcq","prompt":"Choose the correct agreement.","answer":"un vestito verde","explanation":"Verde has the same singular form for masculine and feminine.","options":["un vestito verde","un vestito verda","una vestito verde"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xg20', 'exercise', 'c2w09', 1069, '{"id":"xg20","lessonId":"c2w09","skill":"grammar","type":"mcq","prompt":"Choose the polite formal question.","answer":"Desidera altro?","explanation":"Third-person form marks formal Lei.","options":["Desideri tu altro?","Desidera altro?","Volere altro?"]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt01', 'exercise', 'c1w02', 1070, '{"id":"xt01","lessonId":"c1w02","skill":"writing","type":"input","prompt":"Translate into Italian: We are English but we live in Italy.","answer":"Siamo inglesi ma viviamo in Italia.","explanation":"Model answer: Siamo inglesi ma viviamo in Italia."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt02', 'exercise', 'c1w03', 1071, '{"id":"xt02","lessonId":"c1w03","skill":"writing","type":"input","prompt":"Translate into Italian: My phone number is…","answer":"Il mio numero di telefono è…","explanation":"Model answer: Il mio numero di telefono è…"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt03', 'exercise', 'c1w04', 1072, '{"id":"xt03","lessonId":"c1w04","skill":"writing","type":"input","prompt":"Translate into Italian: She works in a school.","answer":"Lavora in una scuola.","explanation":"Model answer: Lavora in una scuola."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt04', 'exercise', 'c1w05', 1073, '{"id":"xt04","lessonId":"c1w05","skill":"writing","type":"input","prompt":"Translate into Italian: Can we have a table for three?","answer":"Possiamo avere un tavolo per tre?","explanation":"Model answer: Possiamo avere un tavolo per tre?"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt05', 'exercise', 'c1w06', 1074, '{"id":"xt05","lessonId":"c1w06","skill":"writing","type":"input","prompt":"Translate into Italian: On Sundays I never work.","answer":"La domenica non lavoro mai.","explanation":"Model answer: La domenica non lavoro mai."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt06', 'exercise', 'c1w07', 1075, '{"id":"xt06","lessonId":"c1w07","skill":"writing","type":"input","prompt":"Translate into Italian: What time does the film start?","answer":"A che ora comincia il film?","explanation":"Model answer: A che ora comincia il film?"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt07', 'exercise', 'c1w08', 1076, '{"id":"xt07","lessonId":"c1w08","skill":"writing","type":"input","prompt":"Translate into Italian: Breakfast is included in the price.","answer":"La colazione è inclusa nel prezzo.","explanation":"Model answer: La colazione è inclusa nel prezzo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt08', 'exercise', 'c1w11', 1077, '{"id":"xt08","lessonId":"c1w11","skill":"writing","type":"input","prompt":"Translate into Italian: First I get dressed, then I have breakfast.","answer":"Prima mi vesto, poi faccio colazione.","explanation":"Model answer: Prima mi vesto, poi faccio colazione."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt09', 'exercise', 'c1w12', 1078, '{"id":"xt09","lessonId":"c1w12","skill":"writing","type":"input","prompt":"Translate into Italian: You can take the bus here.","answer":"Puoi prendere l’autobus qui.","explanation":"Model answer: Puoi prendere l’autobus qui."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt10', 'exercise', 'c1w13', 1079, '{"id":"xt10","lessonId":"c1w13","skill":"writing","type":"input","prompt":"Translate into Italian: Last week I visited Florence.","answer":"La settimana scorsa ho visitato Firenze.","explanation":"Model answer: La settimana scorsa ho visitato Firenze."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt11', 'exercise', 'c1w14', 1080, '{"id":"xt11","lessonId":"c1w14","skill":"writing","type":"input","prompt":"Translate into Italian: I see them every day. (masculine plural)","answer":"Li vedo ogni giorno.","explanation":"Model answer: Li vedo ogni giorno."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt12', 'exercise', 'c1w15', 1081, '{"id":"xt12","lessonId":"c1w15","skill":"writing","type":"input","prompt":"Translate into Italian: How much do these apples cost?","answer":"Quanto costano queste mele?","explanation":"Model answer: Quanto costano queste mele?"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt13', 'exercise', 'c1w16', 1082, '{"id":"xt13","lessonId":"c1w16","skill":"writing","type":"input","prompt":"Translate into Italian: Our grandparents live in the countryside.","answer":"I nostri nonni vivono in campagna.","explanation":"Model answer: I nostri nonni vivono in campagna."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt14', 'exercise', 'c1w19', 1083, '{"id":"xt14","lessonId":"c1w19","skill":"writing","type":"input","prompt":"Translate into Italian: I go to bed at half past eleven.","answer":"Vado a letto alle undici e mezza.","explanation":"Model answer: Vado a letto alle undici e mezza."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt15', 'exercise', 'c1w20', 1084, '{"id":"xt15","lessonId":"c1w20","skill":"writing","type":"input","prompt":"Translate into Italian: The flat is on the third floor.","answer":"L’appartamento è al terzo piano.","explanation":"Model answer: L’appartamento è al terzo piano."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt16', 'exercise', 'c2w05', 1085, '{"id":"xt16","lessonId":"c2w05","skill":"writing","type":"input","prompt":"Translate into Italian: Go straight and turn left at the traffic light.","answer":"Vai dritto e gira a sinistra al semaforo.","explanation":"Model answer: Vai dritto e gira a sinistra al semaforo."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt17', 'exercise', 'c2w06', 1086, '{"id":"xt17","lessonId":"c2w06","skill":"writing","type":"input","prompt":"Translate into Italian: For dessert I would like the tiramisù.","answer":"Come dolce vorrei il tiramisù.","explanation":"Model answer: Come dolce vorrei il tiramisù."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt18', 'exercise', 'c2w07', 1087, '{"id":"xt18","lessonId":"c2w07","skill":"writing","type":"input","prompt":"Translate into Italian: The keys are in the backpack.","answer":"Le chiavi sono nello zaino.","explanation":"Model answer: Le chiavi sono nello zaino."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt19', 'exercise', 'c2w08', 1088, '{"id":"xt19","lessonId":"c2w08","skill":"writing","type":"input","prompt":"Translate into Italian: Can I try on the blue jacket?","answer":"Posso provare la giacca blu?","explanation":"Model answer: Posso provare la giacca blu?"}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xt20', 'exercise', 'c2w09', 1089, '{"id":"xt20","lessonId":"c2w09","skill":"writing","type":"input","prompt":"Translate into Italian: Unfortunately the lift does not work.","answer":"Purtroppo l’ascensore non funziona.","explanation":"Model answer: Purtroppo l’ascensore non funziona."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl01', 'exercise', 'c1w03', 1090, '{"id":"xl01","lessonId":"c1w03","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Il mio numero è zero due, sette quattro, nove uno.","explanation":"Listen for grouped numbers.","audioText":"Il mio numero è zero due, sette quattro, nove uno."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl02', 'exercise', 'c1w05', 1091, '{"id":"xl02","lessonId":"c1w05","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Sono dodici euro e cinquanta.","explanation":"Prices use euro followed by cents.","audioText":"Sono dodici euro e cinquanta."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl03', 'exercise', 'c1w07', 1092, '{"id":"xl03","lessonId":"c1w07","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Il treno parte alle nove meno un quarto.","explanation":"Meno un quarto means quarter to.","audioText":"Il treno parte alle nove meno un quarto."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl04', 'exercise', 'c1w08', 1093, '{"id":"xl04","lessonId":"c1w08","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"La reception è aperta ventiquattr’ore su ventiquattro.","explanation":"This means open 24 hours a day.","audioText":"La reception è aperta ventiquattr’ore su ventiquattro."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl05', 'exercise', 'c1w11', 1094, '{"id":"xl05","lessonId":"c1w11","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Ogni mattina porto il cane al parco.","explanation":"Ogni mattina signals a routine.","audioText":"Ogni mattina porto il cane al parco."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl06', 'exercise', 'c1w12', 1095, '{"id":"xl06","lessonId":"c1w12","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"La farmacia è dopo il secondo incrocio.","explanation":"Dopo means after or past.","audioText":"La farmacia è dopo il secondo incrocio."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl07', 'exercise', 'c1w13', 1096, '{"id":"xl07","lessonId":"c1w13","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Sabato siamo rimasti a casa.","explanation":"Rimanere uses essere in the perfect tense.","audioText":"Sabato siamo rimasti a casa."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl08', 'exercise', 'c1w15', 1097, '{"id":"xl08","lessonId":"c1w15","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Vorrei mezzo chilo di pomodori.","explanation":"Mezzo chilo is half a kilogram.","audioText":"Vorrei mezzo chilo di pomodori."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl09', 'exercise', 'c1w16', 1098, '{"id":"xl09","lessonId":"c1w16","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Mia sorella minore ha diciannove anni.","explanation":"Minore means younger.","audioText":"Mia sorella minore ha diciannove anni."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl10', 'exercise', 'c1w19', 1099, '{"id":"xl10","lessonId":"c1w19","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Il martedì vado in palestra dopo il lavoro.","explanation":"A definite article with a weekday can indicate habit.","audioText":"Il martedì vado in palestra dopo il lavoro."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl11', 'exercise', 'c1w20', 1100, '{"id":"xl11","lessonId":"c1w20","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"L’affitto è ottocento euro al mese.","explanation":"Al mese means per month.","audioText":"L’affitto è ottocento euro al mese."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl12', 'exercise', 'c2w05', 1101, '{"id":"xl12","lessonId":"c2w05","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"La fermata è proprio davanti al supermercato.","explanation":"Proprio adds exactly/right.","audioText":"La fermata è proprio davanti al supermercato."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl13', 'exercise', 'c2w06', 1102, '{"id":"xl13","lessonId":"c2w06","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Per me un primo, ma niente antipasto.","explanation":"Niente means no/none.","audioText":"Per me un primo, ma niente antipasto."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl14', 'exercise', 'c2w08', 1103, '{"id":"xl14","lessonId":"c2w08","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"Questa camicia costa trentacinque euro.","explanation":"Listen for the price.","audioText":"Questa camicia costa trentacinque euro."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xl15', 'exercise', 'c2w09', 1104, '{"id":"xl15","lessonId":"c2w09","skill":"listening","type":"listen","prompt":"Listen and type exactly what you hear.","answer":"La colazione viene servita dalle sette alle dieci.","explanation":"Dalle… alle… gives a time range.","audioText":"La colazione viene servita dalle sette alle dieci."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr01', 'exercise', 'c2w05', 1105, '{"id":"xr01","lessonId":"c2w05","skill":"reading","type":"reading","prompt":"What must passengers do?","answer":"Validate their ticket.","explanation":"The notice says convalidare il biglietto.","passage":"AVVISO: Prima di salire sull’autobus, convalidare il biglietto. Il biglietto non è valido senza convalida.","options":["Buy a ticket from the driver.","Validate their ticket.","Show a passport."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr02', 'exercise', 'c1w20', 1106, '{"id":"xr02","lessonId":"c1w20","skill":"reading","type":"reading","prompt":"When can you telephone about the flat?","answer":"After 6 p.m.","explanation":"Dopo le ore 18 means after 6 p.m.","passage":"AFFITTASI monolocale arredato, 650 euro al mese, spese incluse. Telefonare dopo le ore 18.","options":["Before 6 a.m.","After 6 p.m.","Only at weekends."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr03', 'exercise', 'c2w06', 1107, '{"id":"xr03","lessonId":"c2w06","skill":"reading","type":"reading","prompt":"Which day is the restaurant closed?","answer":"Monday.","explanation":"Chiuso il lunedì states the closure day.","passage":"TRATTORIA DA LINA — Aperto da martedì a domenica, 12–15 e 19–23. Chiuso il lunedì.","options":["Monday.","Tuesday.","Sunday."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr04', 'exercise', 'c1w12', 1108, '{"id":"xr04","lessonId":"c1w12","skill":"reading","type":"reading","prompt":"Where should patients go at night?","answer":"The emergency entrance.","explanation":"Sul retro means at the back.","passage":"FARMACIA APERTA 8:30–20:00. Per urgenze notturne usare l’ingresso sul retro.","options":["The main entrance.","The emergency entrance at the back.","The station."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr05', 'exercise', 'c2w08', 1109, '{"id":"xr05","lessonId":"c2w08","skill":"reading","type":"reading","prompt":"What is reduced?","answer":"Winter clothing.","explanation":"Capi invernali are winter garments; shoes are excluded.","passage":"SALDI: tutti i capi invernali al 30%. Scarpe escluse. Offerta valida fino a sabato.","options":["Shoes.","Winter clothing.","All summer clothing."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr06', 'exercise', 'c1w07', 1110, '{"id":"xr06","lessonId":"c1w07","skill":"reading","type":"reading","prompt":"At what time is the next screening?","answer":"21:15.","explanation":"The second listed screening is at 21:15.","passage":"CINEMA MODERNO — Oggi: Il viaggio, ore 18:30 e 21:15. Biglietto intero €9, ridotto €6.","options":["18:15.","21:15.","9:00."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr07', 'exercise', 'c1w19', 1111, '{"id":"xr07","lessonId":"c1w19","skill":"reading","type":"reading","prompt":"Why is the class cancelled?","answer":"The teacher is ill.","explanation":"Perché introduces the reason.","passage":"Messaggio: La lezione di italiano di oggi è annullata perché l’insegnante è malata. Recuperiamo venerdì alle 17.","options":["It is a holiday.","The teacher is ill.","There are no students."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr08', 'exercise', 'c2w09', 1112, '{"id":"xr08","lessonId":"c2w09","skill":"reading","type":"reading","prompt":"What should the guest bring?","answer":"An identity document.","explanation":"Mostri un documento d’identità gives the instruction.","passage":"Gentile ospite, la camera è pronta dalle 14. Al check-in mostri un documento d’identità. La reception chiude alle 23.","options":["A printed booking.","An identity document.","Breakfast."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr09', 'exercise', 'c1w15', 1113, '{"id":"xr09","lessonId":"c1w15","skill":"reading","type":"reading","prompt":"What is included in the lunch menu?","answer":"Water and coffee.","explanation":"Inclusi explicitly applies to acqua e caffè.","passage":"MENÙ PRANZO €14: primo o secondo con contorno. Acqua e caffè inclusi. Dolce + €3.","options":["Dessert.","Water and coffee.","Wine."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xr10', 'exercise', 'c1w03', 1114, '{"id":"xr10","lessonId":"c1w03","skill":"reading","type":"reading","prompt":"What information does Anna request?","answer":"The meeting time.","explanation":"A che ora ci vediamo? asks the meeting time.","passage":"Ciao Marco, arrivo a Milano domani mattina. A che ora ci vediamo? Mandami un messaggio. Anna.","options":["The hotel address.","The meeting time.","A train ticket."]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo01', 'exercise', 'c2w01', 1115, '{"id":"xo01","lessonId":"c2w01","skill":"speaking","type":"speak","prompt":"Record a 60-second introduction for a new Italian class.","answer":"Mi chiamo…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Include name, home, work/study, languages and two interests."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo02', 'exercise', 'c1w03', 1116, '{"id":"xo02","lessonId":"c1w03","skill":"writing","type":"speak","prompt":"Complete a short registration form in 4–5 lines.","answer":"Mi chiamo…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Include full name, birth date, nationality, address and phone number."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo03', 'exercise', 'c1w04', 1117, '{"id":"xo03","lessonId":"c1w04","skill":"interaction","type":"speak","prompt":"Role-play a first meeting with a colleague. Ask three questions.","answer":"Che lavoro fai?","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Ask about job, workplace and working hours."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo04', 'exercise', 'c1w05', 1118, '{"id":"xo04","lessonId":"c1w05","skill":"interaction","type":"speak","prompt":"Write your half of a café dialogue from greeting to payment.","answer":"Buongiorno, vorrei…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Order two things, respond to a question and ask for the bill."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo05', 'exercise', 'c1w06', 1119, '{"id":"xo05","lessonId":"c1w06","skill":"speaking","type":"speak","prompt":"Compare two hobbies for 45 seconds.","answer":"Mi piace… ma preferisco…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Say when, where, how often and why."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo06', 'exercise', 'c1w07', 1120, '{"id":"xo06","lessonId":"c1w07","skill":"interaction","type":"speak","prompt":"Arrange a cinema visit with a friend.","answer":"A che ora…?","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Ask the time, suggest a screening and accept or change the plan."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo07', 'exercise', 'c1w08', 1121, '{"id":"xo07","lessonId":"c1w08","skill":"writing","type":"speak","prompt":"Write a 25–35 word hotel booking message.","answer":"Buongiorno, vorrei prenotare…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Include dates, nights, room type and one question."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo08', 'exercise', 'c1w11', 1122, '{"id":"xo08","lessonId":"c1w11","skill":"speaking","type":"speak","prompt":"Describe one ordinary day and one special day.","answer":"Di solito… Oggi invece…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Contrast routine and today using at least five verbs."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo09', 'exercise', 'c1w12', 1123, '{"id":"xo09","lessonId":"c1w12","skill":"interaction","type":"speak","prompt":"Explain where your home is from the station.","answer":"Dalla stazione…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Give three steps using direction and location phrases."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo10', 'exercise', 'c1w13', 1124, '{"id":"xo10","lessonId":"c1w13","skill":"writing","type":"speak","prompt":"Write a 35-word postcard about yesterday.","answer":"Ieri sono andato/a…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Include place, two activities, food and an opinion."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo11', 'exercise', 'c1w15', 1125, '{"id":"xo11","lessonId":"c1w15","skill":"interaction","type":"speak","prompt":"Plan a shopping conversation at a market stall.","answer":"Quanto costano…?","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Ask for two products, quantities and the total price."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo12', 'exercise', 'c1w16', 1126, '{"id":"xo12","lessonId":"c1w16","skill":"speaking","type":"speak","prompt":"Describe a family photograph for one minute.","answer":"Questa è la mia famiglia…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Identify four people and describe appearance or personality."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo13', 'exercise', 'c1w19', 1127, '{"id":"xo13","lessonId":"c1w19","skill":"writing","type":"speak","prompt":"Write a weekly routine with three days and times.","answer":"Il lunedì…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Use frequency expressions and at least one reflexive verb."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo14', 'exercise', 'c1w20', 1128, '{"id":"xo14","lessonId":"c1w20","skill":"interaction","type":"speak","prompt":"Ask five essential questions before renting a flat.","answer":"Quanto costa l’affitto?","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"Cover rent, bills, rooms, location and availability."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('exercise:xo15', 'exercise', 'c2w09', 1129, '{"id":"xo15","lessonId":"c2w09","skill":"speaking","type":"speak","prompt":"Leave a polite voice message reporting a hotel problem.","answer":"Buonasera, sono nella camera…","explanation":"Prioritise a clear message, then check verbs, articles and agreement.","hint":"State room, problem, relevant detail and requested solution."}');
